import json
from datetime import date, datetime, timedelta, timezone
from pathlib import Path
import pytest
from toto_ai.external_odds.goal_api import GoalAPIClient, GoalAPIError
from toto_ai.external_odds.schedule_source_collector import _collect_goal_api_candidates
from tests.test_goal_api_schedule_collection import _queue

DAY=date(2026,8,26)
NOW=datetime(2026,8,25,17,tzinfo=timezone.utc)
def row(identity='a',home='Viking',away='Dinamo Zagreb'):
 return {'id':identity,'apiId':901,'homeTeamName':home,'awayTeamName':away,'homeTeamId':11,'awayTeamId':12,'kickoffUtc':'2026-08-26T19:00:00Z','leagueName':'League','leagueId':3,'matchStatus':'Not Started'}
class Response:
 status_code=200
 headers={}
 def __init__(self,body):self.body=body
 def json(self):return self.body
 def raise_for_status(self):pass
class Pages:
 def __init__(self,pages):self.pages=pages;self.calls=[]
 def get(self,url,*,params,headers,timeout):
  self.calls.append((url,dict(params)))
  i=len(self.calls)-1
  if i>=len(self.pages):raise AssertionError('unexpected extra request')
  rows=self.pages[i]
  return Response({'success':True,'data':rows,'pagination':{'hasMore':i+1<len(self.pages),'nextOffset':int(params['offset'])+len(rows)}})
def client(tmp,pages,*,budget=20,times=None):
 session=Pages(pages);ticks=iter(times) if times else None
 return GoalAPIClient('synthetic',session=session,snapshot_dir=tmp,request_budget=budget,now=(lambda:next(ticks)) if ticks else lambda:NOW),session
@pytest.mark.parametrize('reverse',[False,True])
@pytest.mark.parametrize('one_page',[False,True])
def test_permanent_symmetric_quarantine_and_exact_paging(tmp_path,reverse,one_page):
 a=row();b=a|{'awayTeamHalftimeScore':'1'};pair=[a,b][::-1] if reverse else [a,b];good=row('safe','Gamma','Delta')
 pages=[[*pair,a,good]] if one_page else [[pair[0]],[pair[1]],[a,good]]
 c,s=client(tmp_path,pages);out=c.fetch_schedule_for_collection((DAY,));assert [e.provider_event_id for e in out]==['safe'];assert c.requests_made==len(pages);assert c.schedule_pagination_complete
 conflict,=c.schedule_conflicts;assert len(conflict.observations)==3;assert len(conflict.evidence)==3;assert conflict.differing_fields==('awayTeamHalftimeScore',)
 summaries=conflict.public_summary()['observations'];assert len(summaries)==3
 for observation in summaries:
  raw=json.loads(Path(observation['snapshot_path']).read_text());assert raw['fetched_at']==observation['fetched_at'];assert raw['response_hash']==observation['response_hash']
@pytest.mark.parametrize('status',['Not Started','FINISHED'])
def test_default_still_strict_even_for_terminal_rows(tmp_path,status):
 a=row()|{'matchStatus':status};c,_=client(tmp_path,[[a],[a|{'homeTeamScore':'1'}]])
 with pytest.raises(GoalAPIError,match='duplicate event identity conflicts'):c.fetch_schedule((DAY,))
 assert not c.schedule_pagination_complete

def test_late_metadata_observation_cannot_restore_early_eligibility(tmp_path):
 end=datetime(2026,8,26,19,tzinfo=timezone.utc);a=row();c,_=client(tmp_path,[[a],[a|{'updatedAt':'different'}]],times=[end-timedelta(seconds=1),end]);e,=c.fetch_schedule_for_collection((DAY,));assert not e.eligible and e.captured_at==end;assert not c.schedule_conflicts

def test_budget_counts_raw_conflicted_rows_and_never_returns_prefix(tmp_path):
 a=row();c,s=client(tmp_path,[[a,a|{'homeTeamId':55}],[]],budget=1)
 with pytest.raises(GoalAPIError,match='request budget exhausted'):c.fetch_schedule_for_collection((DAY,))
 assert c.requests_made==1 and len(s.calls)==1 and not c.schedule_pagination_complete and len(c.schedule_conflicts)==1

def test_malformed_later_page_cannot_claim_complete(tmp_path):
 c,_=client(tmp_path,[[row()],[{'id':'bad'}]])
 with pytest.raises((GoalAPIError,ValueError)):c.fetch_schedule_for_collection((DAY,))
 assert not c.schedule_pagination_complete

def test_collector_vetoes_ambiguous_target_without_losing_unaffected_target(tmp_path):
 class Schedule:
  def get(self,url,*,params,headers,timeout):
   a=row();rows=[a,a|{'homeTeamId':44},row('replacement'),row('safe','Gamma','Delta')] if url.endswith('2026-08-26') else []
   return Response({'success':True,'data':rows,'pagination':{'hasMore':False}})
 queue=json.loads(_queue(tmp_path).read_text());queue['records'].append(queue['records'][0]|{'event_order':1,'target_event_id':190002,'home_team':'Gamma','away_team':'Delta'})
 output=tmp_path/'out';c=GoalAPIClient('synthetic',session=Schedule(),snapshot_dir=output/'goal-api-v1',now=lambda:NOW)
 records,status=_collect_goal_api_candidates(queue,output=output,observed=NOW,deadline=datetime(2026,8,26,18,45,tzinfo=timezone.utc),ledger=None,config=None,client=c,team_aliases={'Викинг':'Viking','Динамо Загреб':'Dinamo Zagreb'})
 assert records[0]['status']=='conflict' and records[0]['quarantined_fixture_ids']==['a'];assert records[1]['status']=='independent_candidate' and records[1]['source_event_id']=='safe'
 assert status['candidate_count']==1 and status['quarantined_fixture_count']==1 and status['pagination_complete'];assert not any(x['ledger_eligible'] for x in records)
